import { cn } from "@/lib/utils";

/**
 * SAVO's app icon.
 *
 * The artwork ships as one raster set in `public/`, generated by
 * `scripts/generate-savo-icons.py`: a forest-green tile, a mint receipt, the
 * SAVO shelf label and a stock drawer. Rendering the same PNG the browser
 * installs from means the loading state, the install prompt and the home-screen
 * icon can never drift apart — there is no second drawing of the mark.
 *
 * `detail` is kept for callers that pass it; a raster icon has no alternate
 * detail level, and the favicon sizes already drop the fine rules themselves.
 */
export function AppIcon({
  className,
  title,
}: {
  className?: string;
  /** Accepted for compatibility; the artwork is no longer drawn in two levels. */
  detail?: boolean;
  title?: string;
}) {
  return (
    <img
      src="/icon-192.png"
      alt={title ?? ""}
      aria-hidden={title ? undefined : true}
      className={cn("block rounded-[22%]", className)}
      draggable={false}
    />
  );
}
